function MarketplaceSimulator({ cost, panel, field, money, onBack }: { cost:number; panel:string; field:string; money:(n:number)=>string; onBack:()=>void }) {
  const label = "mb-2 block text-sm font-semibold text-[#536D87]";
  const [marketplace,setMarketplace]=useState("Shopee"); const [fee,setFee]=useState("20"); const [fixed,setFixed]=useState("4"); const [ads,setAds]=useState("0"); const [shipping,setShipping]=useState("0"); const [tax,setTax]=useState("0"); const [salePrice,setSalePrice]=useState("49.90"); const [desiredProfit,setDesiredProfit]=useState("15");
  const totalRate=Math.min(95,Math.max(0,(Number(fee)||0)+(Number(ads)||0)+(Number(tax)||0)))/100; const price=Number(salePrice)||0; const net=price-price*totalRate-(Number(fixed)||0)-(Number(shipping)||0)-cost; const minimum=(cost+(Number(fixed)||0)+(Number(shipping)||0)+(Number(desiredProfit)||0))/(1-totalRate);
  const presets:Record<string,[string,string]>={"Shopee":["20","4"],"Mercado Livre":["13","6.25"],"Amazon":["15","2"],"Elo7":["12","0"],"Loja própria":["4.99","0"],"Outro marketplace":["15","0"]};
  return <div className="animate-in fade-in duration-300"><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-bold text-[#1769FF] hover:underline">← Voltar às ferramentas</button>
    <div className="mx-auto mb-8 max-w-4xl text-center"><p className="mb-2 text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">SIMULADOR DE VENDAS</p><h2 className="text-3xl font-black tracking-tight text-[#173B63] sm:text-4xl">Quanto sobra em cada venda?</h2><p className="mx-auto mt-3 max-w-3xl leading-7 text-[#607C98]">Informe os custos da peça e as taxas da plataforma para descobrir seu lucro real e o preço ideal de venda.</p></div>
    <div className="grid gap-5 xl:grid-cols-[1.05fr_.95fr]"><section className={panel+" p-5 sm:p-6"}><h3 className="text-lg font-extrabold">1. Escolha onde vai vender</h3>
      <label className="mt-4 block"><span className={label}>Marketplace / canal de venda</span><select value={marketplace} onChange={e=>{const v=e.target.value;setMarketplace(v);const p=presets[v];if(p){setFee(p[0]);setFixed(p[1]);}}} className={field}><option>Shopee</option><option>Mercado Livre</option><option>Amazon</option><option>Elo7</option><option>Loja própria</option><option>Outro marketplace</option></select></label>
      <p className="mt-2 rounded-xl bg-[#F3F8FF] p-3 text-xs leading-5 text-[#607C98]">As taxas preenchidas são referências editáveis para simulação. Confira as condições e tarifas vigentes na sua conta antes de anunciar.</p><h4 className="mb-3 mt-7 font-extrabold">2. Custos e taxas da venda</h4>
      <div className="grid gap-4 sm:grid-cols-2">
        <label><span className={label}>Preço de venda (R$)</span><input type="number" min="0" step=".01" value={salePrice} onChange={e=>setSalePrice(e.target.value)} className={field}/></label>
        <label><span className={label}>Custo de produção por peça (R$)</span><input type="number" value={cost.toFixed(2)} readOnly className={field+" bg-[#EAF1F8]"}/><small className="mt-1 block text-[#607C98]">Calculado com os dados da calculadora</small></label>
        <label><span className={label}>Comissão da plataforma (%)</span><input type="number" min="0" max="95" step=".01" value={fee} onChange={e=>setFee(e.target.value)} className={field}/></label>
        <label><span className={label}>Tarifa fixa por venda (R$)</span><input type="number" min="0" step=".01" value={fixed} onChange={e=>setFixed(e.target.value)} className={field}/></label>
        <label><span className={label}>Anúncios / publicidade (%)</span><input type="number" min="0" max="95" step=".1" value={ads} onChange={e=>setAds(e.target.value)} className={field}/></label>
        <label><span className={label}>Impostos (%)</span><input type="number" min="0" max="95" step=".1" value={tax} onChange={e=>setTax(e.target.value)} className={field}/></label>
        <label><span className={label}>Frete pago por você (R$)</span><input type="number" min="0" step=".01" value={shipping} onChange={e=>setShipping(e.target.value)} className={field}/></label>
        <label><span className={label}>Lucro desejado por peça (R$)</span><input type="number" min="0" step=".01" value={desiredProfit} onChange={e=>setDesiredProfit(e.target.value)} className={field}/></label>
      </div></section>
      <section className={panel+" h-fit p-5 sm:p-6"}><p className="text-xs font-black uppercase tracking-widest text-[#1769FF]">RESULTADO DA SIMULAÇÃO</p><h3 className="mt-2 text-xl font-extrabold">Lucro líquido por venda</h3><p className={"mt-4 text-4xl font-black tracking-tight "+(net>=0?"text-emerald-600":"text-red-500")}>{money(net)}</p><p className="mt-1 text-xs text-[#607C98]">Valor estimado que sobra após os custos informados.</p>
        <div className="my-5 space-y-3 border-y border-[#D7E8FF] py-4 text-sm">
          <div className="flex justify-between gap-3"><span className="text-[#607C98]">Preço de venda</span><b>{money(price)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Custo de produção</span><b>{money(cost)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Comissão ({fee}%)</span><b>{money(price*(Number(fee)||0)/100)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Anúncios ({ads}%)</span><b>{money(price*(Number(ads)||0)/100)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Impostos ({tax}%)</span><b>{money(price*(Number(tax)||0)/100)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Tarifa fixa</span><b>{money(Number(fixed)||0)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Frete subsidiado</span><b>{money(Number(shipping)||0)}</b></div>
        </div><div className="rounded-xl bg-[#FFF3E5] p-4"><p className="text-xs font-black uppercase tracking-wider text-[#E85D04]">Preço mínimo sugerido</p><p className="mt-1 text-2xl font-black text-[#173B63]">{money(minimum)}</p><p className="mt-1 text-xs leading-5 text-[#607C98]">Preço para cobrir os custos e alcançar o lucro desejado informado.</p></div><p className="mt-4 text-xs leading-5 text-[#607C98]">Simulação estimada. Tarifas, regras de frete, comissões e impostos podem variar conforme categoria, campanha, modalidade e perfil da conta.</p>
      </section></div></div>;
}

function PrimeArea() {
  const [section,setSection] = useState("Início");
  const [search,setSearch] = useState("");
  const [mobileNav,setMobileNav] = useState(false);
  const [weight,setWeight] = useState("120");
  const [roll,setRoll] = useState("90");
  const [hours,setHours] = useState("4");
  const [hourCost,setHourCost] = useState("1.5");
  const [waste,setWaste] = useState("10");
  const [profit,setProfit] = useState("70");
  const [fee,setFee] = useState("20");
  const filtered = useMemo(()=>categories.filter(c=>c[0].toLowerCase().includes(search.toLowerCase()) || c[1].toLowerCase().includes(search.toLowerCase())),[search]);
  const [energyRate,setEnergyRate] = useState("0.18");
  const [packaging,setPackaging] = useState("2.5");
  const [labor,setLabor] = useState("5");
  const [extraCost,setExtraCost] = useState("0");
  const [tax,setTax] = useState("0");
  const [quantity,setQuantity] = useState("1");
  const [calcMode,setCalcMode] = useState<"choose"|"piece"|"marketplace">("choose");
  const filamentBase = (Number(weight)||0)/1000*(Number(roll)||0);
  const filamentCost = filamentBase*(1+(Number(waste)||0)/100);
  const energyCost = (Number(hours)||0)*(Number(energyRate)||0);
  const machineCost = (Number(hours)||0)*(Number(hourCost)||0);
  const cost = filamentCost+energyCost+machineCost+(Number(packaging)||0)+(Number(labor)||0)+(Number(extraCost)||0);
  const deductions = Math.min(95,Math.max(0,(Number(fee)||0)+(Number(tax)||0)))/100;
  const price = cost*(1+(Number(profit)||0)/100)/(1-deductions);
  const netProfit = price*(1-deductions)-cost;
  const batchTotal = price*(Number(quantity)||0);
  const suggestedPrice = (markup:number) => cost*(1+markup/100)/(1-deductions);
  const title = section === "Biblioteca 3D" ? "Biblioteca" : section;
  const jump = (s:string) => { setSection(s); setMobileNav(false); window.scrollTo({top:0,behavior:"smooth"}); };
  const panel = "rounded-2xl border border-[#D7E8FF] bg-white shadow-[0_12px_40px_rgba(23,105,255,.10)]";
  const button = "inline-flex items-center justify-center gap-2 rounded-xl bg-[#FF7A00] px-4 py-3 text-sm font-extrabold text-white transition-all duration-200 hover:-translate-y-0.5 hover:bg-[#FFB347] hover:shadow-[0_8px_28px_rgba(242,140,40,.18)]";
  const label = "mb-2 block text-sm font-semibold text-[#536D87]";
  const field = "w-full rounded-xl border border-[#D7E8FF] bg-[#F3F8FF] px-3 py-3 text-sm text-[#173B63] outline-none transition focus:border-[#FF7A00] focus:ring-2 focus:ring-[#FF7A00]/15";
  const heading = (eyebrow:string,h:string,desc?:string) => <div className="mx-auto mb-8 max-w-4xl text-center"><p className="mb-2 text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">{eyebrow}</p><h2 className="text-3xl font-black tracking-tight text-[#173B63] sm:text-4xl">{h}</h2>{desc && <p className="mx-auto mt-3 max-w-3xl leading-7 text-[#607C98]">{desc}</p>}</div>;
  const linkButton = (href:string,text:string) => <a className={button} href={href} target={href.startsWith("http")?"_blank":undefined} rel={href.startsWith("http")?"noreferrer":undefined}>{text} <span aria-hidden>↗</span></a>;

  return <div className="min-h-screen bg-[#EFF6FF] text-[#173B63] md:flex">
    <aside className={`fixed inset-y-0 left-0 z-40 flex h-dvh w-[276px] flex-col border-r border-white/10 bg-[#111827] p-4 transition-transform duration-300 md:sticky md:top-0 md:h-screen md:translate-x-0 ${mobileNav?"translate-x-0":"-translate-x-full"}`}>
      <button onClick={()=>jump("Início")} className="mb-8 flex w-full items-center justify-center px-2 pt-2"><img src={logoUrl} alt="Prime 3D Biblioteca" className="h-auto w-full max-w-[215px] object-contain"/></button>
      <div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.22em] text-slate-300">Área do assinante</div>
      <nav className="flex flex-1 flex-col gap-1">{nav.map(([name,icon])=><button key={name} onClick={()=>jump(name)} className={`group flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition-all duration-200 ${section===name?"bg-[#FF7A00] text-white shadow-[0_6px_22px_rgba(242,140,40,.18)]":"text-slate-300 hover:bg-white/10 hover:text-white"}`}><span className="text-base transition-transform group-hover:scale-110">{icon}</span>{name}{section===name&&<span className="ml-auto h-1.5 w-1.5 rounded-full bg-white"/>}</button>)}</nav>
      <div className="mt-5 border-t border-white/10 px-3 pt-4"><p className="truncate text-xs text-slate-400">Área exclusiva Prime Projetos 3D</p></div>
    </aside>
    {mobileNav&&<button aria-label="Fechar menu" onClick={()=>setMobileNav(false)} className="fixed inset-0 z-30 bg-black/60 md:hidden"/>}
    <main className="min-w-0 flex-1">
      <header className="sticky top-0 z-20 flex items-center gap-3 border-b border-[#D7E8FF] bg-white/95 shadow-[0_4px_18px_rgba(23,105,255,.06)] px-4 py-4 backdrop-blur-xl sm:px-7">
        <button onClick={()=>setMobileNav(true)} className="rounded-lg border border-[#D7E8FF] bg-[#EFF6FF] px-3 py-2 text-[#1769FF] md:hidden" aria-label="Abrir menu">☰</button>
        <div className="min-w-0 flex-1"><p className="text-[10px] font-black uppercase tracking-[.16em] text-[#FF7A00]">PRIME PROJETOS 3D <span className="text-[#A9C8F2]">/ ÁREA DE MEMBROS</span></p><h1 className="truncate text-lg font-bold sm:text-xl">{title}</h1></div>
        <label className="hidden w-full max-w-xs items-center gap-2 rounded-xl border border-[#D7E8FF] bg-[#F3F8FF] px-3 py-2.5 focus-within:border-[#FF7A00]/70 sm:flex"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar categoria..." className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-[#A9C8F2]"/></label>
        <span className="hidden rounded-full border border-[#FF7A00]/20 bg-[#FFF0DF] px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-[#FF7A00] lg:inline-flex">Acesso liberado</span>
      </header>
      <div className="mx-auto max-w-[1500px] px-4 py-7 sm:px-7 sm:py-9">
        {section==="Leia antes de começar" && <div className="space-y-5 animate-in fade-in duration-300">
          {heading("LEIA ANTES DE COMEÇAR","Bem-vindo ao Prime Projetos 3D 👋","1 minuto de leitura pra você saber exatamente o que tem aqui.")}
          <section className={`${panel} border-[#FF7A00]/40 p-5 sm:p-6`}><h3 className="text-center text-2xl font-extrabold">O que é o Prime Projetos 3D</h3><p className="mx-auto mt-3 max-w-5xl text-center leading-7 text-[#536D87]">O Prime Projetos 3D é uma <b className="text-[#173B63]">biblioteca de arquivos STL já prontos, separados e organizados por categoria</b>. A gente não cria os modelos: reunimos arquivos que já existem, muitos vindos de repositórios abertos como <b>MakerWorld, Printables e Thingiverse</b>, e fizemos a parte chata por você: procurar, baixar, separar e organizar tudo em pastas, pra você ir direto pra impressora.</p>
            <div className="mt-5 grid gap-3 lg:grid-cols-3">{[
              ["✅ O que você recebe",["Milhares de arquivos prontos pra fatiar","Tudo organizado por pasta e categoria","Natal separado numa pasta só","Calculadora de custo e painel de vendas","Bônus pra precificar, fotografar e vender"]],
              ["❌ O que não é",["Não são modelos inéditos ou criados por nós","Não é um lançamento exclusivo de peças","A mesma peça pode existir em outros sites"]],
              ["💡 Por que vale a pena",["Você economiza horas procurando modelo um por um","Encontra tudo num lugar só, por categoria","Tem as ferramentas pra calcular preço e vender"]]
            ].map(([t,items])=><div key={String(t)} className="rounded-xl border border-white/[.08] bg-[#F3F8FF] p-4 transition duration-200 hover:border-[#FF7A00]/30 hover:bg-[#E7F2FF]"><h4 className="font-extrabold">{t}</h4><ul className="mt-3 space-y-2 text-sm leading-5 text-[#607C98]">{(items as string[]).map(i=><li key={i} className="flex gap-2"><span className="text-[#FF7A00]">•</span>{i}</li>)}</ul></div>)}</div>
          </section>
          <section className={`${panel} p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">O QUE VOCÊ JÁ TEM NAS MÃOS</p><h3 className="mt-2 text-center text-xl font-extrabold">Quanto tempo isso te economiza</h3><div className="mt-4 grid grid-cols-2 gap-3 xl:grid-cols-4">{[["+90 mil","arquivos já separados por categoria"],["27","categorias prontas pra navegar"],["+400","modelos de Natal numa pasta só"],["6","bônus pra precificar, fotografar e vender"]].map(([n,t])=><div key={n} className="rounded-xl border border-[#D7E8FF] bg-[#F3F8FF] p-4 text-center transition hover:-translate-y-1 hover:border-[#FF7A00]/40"><div className="text-3xl font-black tracking-tight text-[#FF7A00]">{n}</div><p className="mt-2 text-sm leading-5 text-[#607C98]">{t}</p></div>)}</div><p className="mt-4 leading-7 text-[#536D87]">Achar, baixar, testar e organizar esse volume de arquivos sozinho leva <b>semanas</b> de pesquisa em vários sites, um modelo por vez. Aqui você abre a categoria e já está tudo junto. Junto vêm as ferramentas que esses sites não têm: <b>calculadora de lucro por peça, calendário de produção de Natal, lista das 30 peças com preço sugerido e painel de vendas</b>.</p></section>
          <section className={`${panel} p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">SUA PRIMEIRA VITÓRIA HOJE</p><h3 className="mt-2 text-center text-xl font-extrabold">Faça isso nas próximas 24 horas</h3><ol className="mt-4 space-y-3">{["Abra Natal e escolha 3 peças pequenas (bola, estrela, enfeite).","Imprima a primeira e coloque peso e tempo na Calculadora.","Tire a foto seguindo o Guia de Fotos e poste no seu WhatsApp ou Instagram."].map((s,i)=><li key={s} className="flex gap-3 rounded-xl bg-white/[.03] p-3"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[#FF7A00] font-black text-black">{i+1}</span><span className="self-center text-[#536D87]">{s}</span></li>)}</ol><p className="mt-4 text-sm leading-6 text-[#607C98]">Quem imprime e posta a primeira peça no primeiro dia é quem tira o maior proveito da biblioteca. O resultado vem de imprimir, não de ficar só olhando as pastas.</p></section>
          <section className={`${panel} flex flex-col gap-4 border-[#FF7A00]/25 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6`}><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">TRAVOU EM ALGUMA COISA?</p><h3 className="mt-2 text-xl font-extrabold">Fale com a gente antes de desistir</h3><p className="mt-2 max-w-3xl leading-6 text-[#607C98]">Não achou o modelo que queria, um link não abriu ou ficou em dúvida sobre como imprimir ou precificar? Manda um e-mail que a gente te ajuda a encontrar o arquivo certo e a começar.</p><p className="mt-2 text-xs text-[#B7D2F4]">Sua garantia de 7 dias continua valendo do mesmo jeito. Só pedimos a chance de te ajudar primeiro.</p></div>{linkButton("mailto:botelhoenzo7@gmail.com","✉ CHAMAR NO E-MAIL")}</section>
          <section className={`${panel} flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6`}><div><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">🎓 NUNCA IMPRIMIU UM ARQUIVO BAIXADO?</p><h3 className="mt-2 text-xl font-extrabold">Veja o passo a passo completo no Guia do Iniciante.</h3></div><button className={button} onClick={()=>jump("Guia do Iniciante")}>ABRIR GUIA →</button></section>
          <section className={`${panel} p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">COMO USAR</p><h3 className="mt-2 text-center text-xl font-extrabold">Seu passo a passo</h3><ol className="mt-4 grid gap-3 md:grid-cols-2">{["Biblioteca 3D: escolha a categoria e baixe os arquivos pelo Google Drive.","Fatie e teste: imprima 1 unidade de cada modelo antes de anunciar.","Calculadora: veja quanto custa cada peça e por quanto vender.","Bônus: use o calendário de Natal, o Top 30 e o guia de fotos pra vender.",].map((t,i)=><li key={t} className="flex gap-3 rounded-xl bg-white/[.03] p-4"><span className="font-black text-[#FF7A00]">0{i+1}</span><span className="text-sm leading-6 text-[#536D87]">{t}</span></li>)}</ol><p className="mt-4 text-sm text-[#B7D2F4]">Não encontrou algo ou um link não abre? Consulte os canais de atendimento informados na sua confirmação de compra.</p><button onClick={()=>jump("Início")} className={`${button} mt-5`}>ENTENDI, VER A BIBLIOTECA →</button></section>
        </div>}
        {section==="Guia do Iniciante" && <div className="space-y-5 animate-in fade-in duration-300">{heading("GUIA DO INICIANTE","Do arquivo à peça pronta 🎓","Nunca imprimiu um arquivo baixado? Siga este passo a passo na ordem. Leva uns 10 minutos pra ler.")}<div className={`${panel} p-5 sm:p-7`}><p className="text-xs font-black uppercase tracking-widest text-[#FF7A00]">NESTE GUIA</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{["Entenda os arquivos","Instale o programa da sua impressora","Passo a passo da primeira impressão","Como mandar pra impressora (por marca)","Modelos com várias peças e várias cores","Configurações seguras pra começar","Deu problema? Soluções rápidas","Dicionário do iniciante"].map((s,i)=><a href={`#guide-${i+1}`} key={s} className="rounded-lg border border-white/[.07] bg-white/[.025] p-3 text-sm text-[#536D87] transition hover:border-[#FF7A00]/40 hover:text-[#FF7A00]"><span className="mr-3 font-black text-[#FF7A00]">0{i+1}</span>{s}</a>)}</div></div>
          {[
            ["Entenda os arquivos",<><p>Cada modelo da biblioteca fica numa pasta do Google Drive. Dentro dela você vai encontrar:</p><p><b>📷 Foto (.jpg / .png)</b> É só a prévia, pra você ver como a peça fica. <b>Não vai pra impressora.</b></p><p><b>🧊 .STL</b> O formato da peça. Abre em qualquer programa de impressão 3D. Você escolhe cor e configurações.</p><p><b>📦 .3MF</b> Um “projeto pronto”: pode trazer várias peças, as cores e as placas já organizadas. É o melhor formato quando existe.</p><p><b>🗜️ .ZIP / .RAR</b> Pasta compactada. Baixe e <b>descompacte</b> (botão direito → Extrair) antes de abrir.</p><p className="rounded-xl bg-[#FF7A00]/10 p-3 text-sm text-[#E85D04]">💡 Pelo celular você só vê as fotos. O arquivo de impressão (.STL ou .3MF) precisa ser aberto num programa no computador. Entre na área de membros pelo computador pra baixar com mais facilidade.</p></>],
            ["Instale o programa da sua impressora",<><p>A impressora não lê o arquivo .STL/.3MF direto. Antes ele passa por um programa chamado <b>fatiador</b>, que transforma a peça em camadas e cria as instruções de impressão. Todos esses são grátis:</p><p><b>Bambu Lab</b> (A1, A1 mini, P1S, X1...) ➜ <a className="text-[#FF7A00] underline" href="https://bambulab.com/en/download/studio" target="_blank" rel="noreferrer">Bambu Studio</a>. Abre os .3mf da biblioteca com placas e cores certinhas.</p><p><b>Creality</b> (Ender, K1, K2, Hi...) ➜ <a className="text-[#FF7A00] underline" href="https://www.creality.com/pages/download" target="_blank" rel="noreferrer">Creality Print</a> (ou OrcaSlicer).</p><p><b>Elegoo, Anycubic, Prusa, Sovol, outras</b> ➜ <a className="text-[#FF7A00] underline" href="https://github.com/SoftFever/OrcaSlicer/releases" target="_blank" rel="noreferrer">OrcaSlicer</a> (funciona com quase todas) ou o programa da própria marca.</p><p><b>Qualquer impressora</b> ➜ <a className="text-[#FF7A00] underline" href="https://ultimaker.com/software/ultimaker-cura/" target="_blank" rel="noreferrer">UltiMaker Cura</a> também funciona, mas às vezes abre só a primeira peça de um .3mf.</p><p>Na primeira vez que abrir o programa, ele pede pra escolher o modelo da sua impressora. Escolha certinho: é isso que deixa as configurações corretas.</p></>],
            ["Passo a passo da primeira impressão",<ol className="list-decimal space-y-2 pl-5"><li><b>Baixe o arquivo</b> .STL ou .3MF da pasta do modelo (no computador). Se vier .zip, descompacte.</li><li><b>Abra no fatiador:</b> arraste o arquivo pra dentro do programa, ou use Arquivo → Abrir / Importar. Se for .3mf, use Abrir projeto.</li><li><b>Escolha o filamento:</b> pra começar, use PLA. É o mais fácil.</li><li><b>Confira a posição:</b> a peça precisa estar apoiada na mesa pela parte mais plana.</li><li><b>Suporte:</b> só ligue se a peça tiver partes “no ar”. Articulados e brinquedos sensoriais normalmente são feitos pra imprimir sem suporte.</li><li><b>Fatie:</b> clique em Fatiar. O programa mostra o tempo e a quantidade de filamento (anote na Calculadora).</li><li><b>Mande pra impressora</b> (veja o passo 4).</li><li><b>Acompanhe a primeira camada.</b> Se ela grudar bem, o resto quase sempre dá certo.</li></ol>],
            ["Como mandar pra impressora",<><p><b>Bambu Lab (A1, A1 mini, P1S, X1)</b></p><ol className="list-decimal space-y-1 pl-5"><li>No Bambu Studio, entre com a mesma conta Bambu que está na impressora.</li><li>Clique em Fatiar placa e depois em Imprimir: ele envia pela internet direto pra impressora.</li><li>Sem Wi-Fi? Use Exportar G-code fatiado, salve no cartão microSD e coloque na impressora.</li><li>Com AMS, escolha qual filamento vai em cada cor antes de imprimir.</li></ol><p><b>Creality (Ender, K1, K2, Hi)</b></p><ol className="list-decimal space-y-1 pl-5"><li>No Creality Print, escolha seu modelo, fatie e clique em Imprimir.</li><li>K1, K2 e modelos com Wi-Fi: envie pela rede.</li><li>Ender e modelos sem Wi-Fi: exporte G-code, salve no cartão SD/pendrive e selecione no visor.</li><li>Creality Cloud funciona melhor com .STL. Se um .3mf abrir com peças faltando, fale com a gente.</li></ol><p><b>Outras marcas</b> (Elegoo, Anycubic, Prusa, Sovol...): no OrcaSlicer ou programa da marca, escolha a impressora, fatie, exporte G-code e salve no cartão SD/pendrive.</p></>],
            ["Modelos com várias peças e várias cores",<><p>Muitos modelos (ursinho com gorro, boneco de neve, Papai Noel) vêm em várias peças pra montar ou colar depois.</p><ul className="list-disc space-y-2 pl-5"><li><b>Placas:</b> num .3mf, as peças podem estar divididas em Placa 1, Placa 2... Confira todas.</li><li><b>Lista de objetos:</b> no lado direito do programa aparecem todas as peças do arquivo.</li><li><b>Impressora de uma cor só:</b> imprima por cor. Depois encaixe ou cole.</li><li><b>Impressora com sistema de cores:</b> dá pra imprimir tudo junto, escolhendo a cor de cada peça.</li><li><b>Cola:</b> cola instantânea (tipo Super Bonder) funciona bem em PLA.</li></ul></>],
            ["Configurações seguras pra começar",<><p>O perfil padrão do programa pra sua impressora já funciona. Se quiser um ponto de partida:</p><div className="grid gap-2 sm:grid-cols-2">{[["Filamento","PLA"],["Altura de camada","0,20 mm"],["Preenchimento","15%"],["Paredes","2 a 3"],["Suporte","Só se precisar"],["Aderência","Borda (brim) em peças altas ou finas"]].map(([k,v])=><div key={k} className="flex justify-between gap-4 rounded-lg bg-[#F3F8FF] p-3"><span className="text-[#607C98]">{k}</span><b>{v}</b></div>)}</div><p className="rounded-xl bg-[#FFF0DF] p-3 text-sm text-[#E85D04]">⚠️ Articulados e “imprime pronto” (print-in-place): não mude muito a escala nem ligue suporte. As juntas foram desenhadas pra soltar na medida certa.</p></>],
            ["Deu problema? Soluções rápidas",<div className="space-y-3">{[["A peça não gruda na mesa","Limpe a mesa com álcool isopropílico, faça o nivelamento e use borda (brim)."],["Abriu só uma parte do modelo","Veja as outras placas no topo do programa. Se abrir só a primeira, fale com a gente que mandamos em .STL separado."],["A peça é maior que a minha mesa","Diminua a escala (ex.: 80%) ou gire a peça. Evite mexer na escala de articulados."],["Fios de plástico entre as partes","É o stringing: geralmente filamento úmido ou temperatura alta. Abaixe uns 5 °C e guarde o filamento fechado."],["A articulação ficou travada","Mexa com cuidado logo depois de imprimir, ainda morna. Se não soltar, confira se o suporte estava desligado."],["O arquivo não abre","Se for .zip, descompacte primeiro. Se for .3mf, use Abrir projeto. Ainda não abriu? Chama a gente no Suporte."]].map(([q,a])=><div key={q}><b>{q}</b><p>{a}</p></div>)}</div>],
            ["Dicionário do iniciante",<div className="grid gap-3 sm:grid-cols-2">{[["Fatiador","Programa que transforma a peça em camadas e prepara a impressão."],["Fatiar","O momento em que o programa calcula as camadas, o tempo e o filamento."],["G-code","O arquivo final, já fatiado, que a impressora entende."],["Placa (plate)","Cada mesa de impressão dentro de um projeto .3mf."],["Suporte","Estrutura provisória que segura partes no ar. Sai depois de imprimir."],["Preenchimento (infill)","O recheio de dentro da peça. Mais preenchimento = peça mais firme e mais filamento."],["Borda (brim)","Contorno fino em volta da peça pra ela grudar melhor na mesa."],["Print-in-place","Peça articulada que já sai montada da impressora."]].map(([q,a])=><div key={q} className="rounded-xl bg-white/[.035] p-3"><b>{q}</b><p>{a}</p></div>)}</div>]
          ].map(([name,body],i)=><section id={`guide-${i+1}`} key={String(name)} className={`${panel} scroll-mt-24 p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-widest text-[#FF7A00]">PASSO {i+1}</p><h3 className="mb-4 mt-2 text-xl font-extrabold">{name}</h3><div className="space-y-3 leading-7 text-[#536D87] [&_li]:text-[#536D87] [&_p]:leading-7">{body}</div></section>)}
          <section className={`${panel} flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between`}><div><h3 className="text-xl font-extrabold">Travou em algum passo?</h3><p className="mt-2 text-[#607C98]">Manda a dúvida pra gente com o nome do modelo e a sua impressora.</p></div><button onClick={()=>jump("Suporte")} className={button}>✉ IR PARA O SUPORTE</button></section></div>}
        {section==="Início" && <div className="space-y-8 animate-in fade-in duration-300">
          <section id="novidades" className="overflow-hidden rounded-3xl border border-[#D7E8FF] bg-white shadow-[0_16px_50px_rgba(23,105,255,.10)]">
            
            <div className="grid gap-8 bg-gradient-to-br from-[#155EEF] via-[#287BFF] to-[#0EA5E9] px-6 py-9 text-white sm:px-10 sm:py-12 lg:grid-cols-[1.2fr_.8fr] lg:items-center">
              <div><span className="inline-flex rounded-full border border-white/30 bg-white/15 px-3 py-1.5 text-[10px] font-black uppercase tracking-[.16em] text-white">ACESSO LIBERADO</span><p className="mt-5 text-xs font-black uppercase tracking-[.2em] text-[#FFB347]">PRIME PROJETOS 3D</p><h2 className="mt-3 max-w-3xl text-4xl font-black leading-[1.08] tracking-tight text-white sm:text-5xl">Sua impressora 3D agora tem o que imprimir.</h2><p className="mt-5 max-w-2xl text-base leading-7 text-blue-50/90">Mais de <b className="text-white">100 mil arquivos STL</b> prontos, testados e organizados pelo que mais vende. É só baixar, imprimir e vender, <b className="text-white">sem modelar nada.</b></p><div className="mt-7 flex flex-wrap gap-3"><button onClick={()=>document.getElementById("biblioteca-inicio")?.scrollIntoView({behavior:"smooth"})} className={button}>EXPLORAR BIBLIOTECA ↓</button><button onClick={()=>jump("Leia antes de começar")} className="rounded-xl border border-white/25 px-4 py-3 text-sm font-extrabold text-white transition hover:bg-white/10">COMO FUNCIONA</button></div></div>
              <div className="grid grid-cols-2 gap-3">{[["+100 mil","arquivos STL"],["1.052","módulos e modelos"],["30","categorias"],["+2.309","novos em 28 dias"]].map(([n,t])=><div key={t} className="rounded-2xl border border-white/15 bg-white/15 p-4 sm:p-5"><p className="text-2xl font-black tracking-tight text-[#FFB347] sm:text-3xl">{n}</p><p className="mt-2 text-xs font-semibold leading-5 text-blue-50/90">{t}</p></div>)}</div>
            </div>
          </section>

          <section className="space-y-4"><div className="text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">VANTAGENS EXTRAS</p><h2 className="mt-2 text-2xl font-black tracking-tight text-[#173B63] sm:text-3xl">Além dos arquivos, você também recebe</h2><p className="mt-2 text-sm text-[#607C98]">Ferramentas e materiais para produzir melhor e transformar impressões em vendas.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {[["/natal-n4.webp","Templates de Natal","Artes e materiais para preparar suas divulgações da temporada.","VER BÔNUS","Bônus"],["calculator","Calculadora e precificação","Calcule filamento, energia, tempo de máquina, embalagem, taxas, mão de obra e preço de venda.","ABRIR CALCULADORA","Calculadora"],["printer","Impressora 3D Mais Rápida","Ajustes para reduzir o tempo de impressão e produzir mais peças por dia.","VER BÔNUS","Bônus"],["/comunidade-telegram.webp","Comunidade de impressão 3D","Encontre grupos para trocar experiências, ideias e modelos.","ACESSAR COMUNIDADE","Comunidade"]].map(([img,t,d,b,dest])=><article key={t} className="overflow-hidden rounded-2xl border border-[#D7E8FF] bg-white transition hover:-translate-y-1 hover:border-[#FF7A00]/50"><div className="relative h-40 overflow-hidden bg-[#F3F8FF] sm:h-44">{img==="calculator"?<div className="flex h-full w-full items-center justify-center bg-[#1769FF]"><svg viewBox="0 0 96 96" className="h-20 w-20" fill="none" aria-hidden="true"><rect x="22" y="10" width="52" height="76" rx="9" stroke="white" strokeWidth="5"/><rect x="31" y="20" width="34" height="15" rx="3" fill="white"/><path d="M34 48h5m9 0h5m9 0h1M34 60h5m9 0h5m9 0h1M34 72h5m9 0h5m9 0h1" stroke="#FFB347" strokeWidth="5" strokeLinecap="round"/></svg></div>:img==="printer"?<div className="flex h-full w-full items-center justify-center bg-[#1769FF]"><svg viewBox="0 0 96 96" className="h-20 w-20" fill="none" aria-hidden="true"><path d="M30 13h36v18H30z" stroke="white" strokeWidth="5" strokeLinejoin="round"/><path d="M20 36h56a8 8 0 0 1 8 8v20H68v19H28V64H12V44a8 8 0 0 1 8-8Z" stroke="white" strokeWidth="5" strokeLinejoin="round"/><path d="M36 53h24M36 64h24M36 75h24" stroke="#FFB347" strokeWidth="5" strokeLinecap="round"/><path d="m68 18 8-8m-8 8 8 8" stroke="#FFB347" strokeWidth="4" strokeLinecap="round"/></svg></div>:<img src={img} alt={t} loading="lazy" className="h-full w-full object-cover object-center"/>}</div><div className="p-5"><h3 className="text-lg font-extrabold text-[#173B63]">{t}</h3><p className="mt-2 min-h-12 text-sm leading-6 text-[#607C98]">{d}</p><button onClick={()=>jump(dest as string)} className="mt-4 text-xs font-black tracking-wide text-[#F05A00] hover:underline">{b} →</button></div></article>)}
          </div></section>

          <section className="overflow-hidden rounded-3xl border border-[#D7E8FF] bg-white shadow-[0_12px_40px_rgba(18,56,90,.06)]">
            <div className="grid gap-6 p-5 sm:p-8 lg:grid-cols-[.72fr_1.28fr] lg:items-center">
              <div className="overflow-hidden rounded-2xl bg-[#EEF6FF]"><img src="https://img.taidon.app/3d/guia-capa.webp" alt="Capa do Guia Definitivo de Impressão 3D" loading="lazy" className="mx-auto max-h-[420px] w-full object-contain"/></div>
              <div><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">GUIA EM PDF · 30 PÁGINAS</p><h2 className="mt-2 text-3xl font-black tracking-tight text-[#173B63]">Guia Definitivo de Impressão 3D</h2><p className="mt-3 leading-7 text-[#607C98]">Do download à peça perfeita: aprenda sobre fatiador, camadas, suportes, erros comuns e acabamento. Um passo a passo para acompanhar desde a escolha do arquivo até a finalização da peça.</p><div className="mt-5 grid gap-2 sm:grid-cols-3">{[["01","Prepare o computador"],["02","Baixe seu arquivo"],["03","Prepare e imprima"]].map(([n,t])=><div key={n} className="rounded-xl bg-[#F3F8FF] p-3"><span className="text-xs font-black text-[#FF7A00]">{n}</span><p className="mt-1 text-sm font-bold text-[#173B63]">{t}</p></div>)}</div><div className="mt-6 flex flex-wrap gap-3"><a href="https://bibliotecamakerpro-membros.netlify.app/guia/guia-definitivo-impressao-3d.pdf" target="_blank" rel="noreferrer" className={button}>BAIXAR GUIA EM PDF ↓</a><a href="https://bibliotecamakerpro-membros.netlify.app/guia/guia-definitivo-impressao-3d.pdf" target="_blank" rel="noreferrer" className="inline-flex items-center rounded-xl border border-[#D7E8FF] px-4 py-3 text-sm font-extrabold text-[#173B63] transition hover:border-[#FF7A00]">ABRIR NO NAVEGADOR ↗</a></div><p className="mt-3 text-xs text-[#A9C8F2]">30 páginas · Consulte o mapa de assuntos e avance direto para cada etapa.</p></div>
            </div>
          </section>

          <section id="biblioteca-inicio" className="scroll-mt-24"><div className="mb-5 text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">EXPLORE OS MÓDULOS</p><h2 className="mt-2 text-3xl font-black tracking-tight text-[#173B63]">Biblioteca completa de arquivos</h2><p className="mt-2 text-sm text-[#607C98]">Escolha uma categoria e acesse as pastas organizadas no Google Drive.</p></div><div className="mb-5 flex flex-col items-center gap-3 sm:flex-row sm:justify-center"><span className="text-center text-xs font-black tracking-widest text-[#FF7A00]">{categories.length} CATEGORIAS DISPONÍVEIS</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar entre as categorias..." className={field+" sm:max-w-xs"}/></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(([name,desc,icon,url],i)=><article key={name} className="group overflow-hidden rounded-2xl border border-[#D7E8FF] bg-white shadow-[0_8px_24px_rgba(18,56,90,.05)] transition-all duration-200 hover:-translate-y-1 hover:border-[#FF7A00]/50"><div className="relative h-40 overflow-hidden bg-[#E8F3FF] sm:h-44">{categoryImages[name] ? <img src={categoryImages[name]} alt={"Prévia da categoria "+name} loading="lazy" decoding="async" className="h-full w-full object-cover object-center"/> : <div className="flex h-full w-full flex-col items-center justify-center gap-3 text-[#FF7A00]"><span className="text-5xl">{icon}</span><span className="text-[10px] font-black uppercase tracking-[.2em] text-[#A9C8F2]">Imagem em breve</span></div>}</div><div className="p-4"><div className="flex justify-center"><span className="rounded-full bg-[#E7F2FF] px-3 py-1 text-[9px] font-black tracking-widest text-[#1769FF]">ARQUIVOS ORGANIZADOS</span></div><h3 className="mt-3 text-center text-lg font-extrabold text-[#173B63]">{name}</h3><p className="mt-2 min-h-10 text-center text-sm leading-5 text-[#607C98]">{desc}</p>{name==="Natal"&&<p className="mt-3 text-center text-xs font-bold text-[#F05A00]">✨ ESPECIAL DE NATAL</p>}{categoryExtraLinks[name] ? <div className="mt-4 grid grid-cols-2 gap-2">{categoryExtraLinks[name].map(link=><a key={link.url} href={link.url} target="_blank" rel="noreferrer" className={button+" w-full px-2 text-xs"}>{link.label} ↗</a>)}</div> : <a href={url} target="_blank" rel="noreferrer" className={button+" mt-4 w-full"}>ACESSAR ARQUIVOS ↗</a>}</div></article>)}</div></section>

          <section className="rounded-3xl border border-[#D7E8FF] bg-white p-5 shadow-[0_8px_28px_rgba(18,56,90,.05)] sm:p-8"><div className="text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">CENTRAL DE AJUDA</p><h2 className="mt-2 text-2xl font-black text-[#173B63] sm:text-3xl">Dúvidas rápidas</h2><p className="mt-2 text-sm text-[#607C98]">Respostas para começar a usar sua biblioteca sem complicação.</p></div><div className="mx-auto mt-6 max-w-4xl divide-y divide-[#D7E8FF]">{[["Preciso baixar os 100 mil arquivos de uma vez?","Não. Tudo fica organizado por módulo. Você abre a pasta e baixa só o que for imprimir."],["O arquivo não abriu ou deu erro no fatiador. E agora?","Primeiro confirme que descompactou o .zip com o WinRAR. Se o fatiador mostrar um aviso de erro, clique em Reparar e aguarde até o fim. Depois é só fatiar de novo."],["Meu modelo veio com mais de um arquivo.","Alguns modelos têm o corpo e as partes, por exemplo olhos e nariz. Importe o corpo e depois as partes no mesmo projeto. Imprimir tudo junto é opcional: você pode imprimir uma peça de cada vez."],["Preciso usar suporte na impressão?","Depende da peça. Peças maiores ou sem uma base firme costumam precisar. No fatiador, ative Habilitar suporte e fatie; se o suporte ficar desnecessário, desmarque e fatie de novo."],["Posso vender o que eu imprimir?","Pode imprimir e vender as peças físicas, respeitando a licença aplicável a cada modelo. Confira sempre as permissões do criador e os direitos de marcas e personagens de terceiros."]].map(([q,a])=><details key={q} className="group py-4"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 font-bold text-[#173B63] marker:hidden">{q}<span className="text-xl font-black text-[#FF7A00] transition group-open:rotate-45">+</span></summary><p className="mt-3 max-w-3xl pr-8 text-sm leading-7 text-[#607C98]">{a}</p></details>)}</div></section>
        </div>}
        {section==="Biblioteca 3D" && <div className="animate-in fade-in duration-300">{heading("BIBLIOTECA EXCLUSIVA","Biblioteca 3D","Modelos organizados por categoria, prontos pra fatiar.")}<section className={`${panel} mb-5 border-[#FF7A00]/25 p-4 sm:p-5`}><p className="text-sm leading-6 text-[#536D87]">📂 <b>Arquivos prontos e organizados por categoria, não são modelos inéditos.</b> Muitos vêm de repositórios abertos (MakerWorld, Printables, Thingiverse). O nosso trabalho foi reunir, separar e organizar tudo pra você imprimir sem perder tempo procurando.</p></section><div className="mb-5 flex flex-col items-center gap-3 sm:flex-row sm:justify-center"><span className="text-center text-xs font-black tracking-widest text-[#FF7A00]">ARQUIVOS ORGANIZADOS · {filtered.length} CATEGORIAS</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar entre as categorias..." className={`${field} sm:max-w-xs`}/></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(([name,desc,icon,url],i)=><article key={name} className={`${panel} group overflow-hidden transition-all duration-200 hover:-translate-y-1 hover:border-[#FF7A00]/40`}><div className="relative h-44 overflow-hidden bg-[#F3F8FF] sm:h-48">{categoryImages[name] ? <img src={categoryImages[name]} alt={"Prévia da categoria " + name} loading="eager" decoding="async" className="h-full w-full object-cover object-center"/> : <div className="flex h-full w-full flex-col items-center justify-center gap-3 bg-[radial-gradient(ellipse_at_center,_rgba(242,140,40,0.10),_transparent_65%)] text-[#FF7A00]"><span className="text-5xl opacity-90">{icon}</span><span className="text-[10px] font-black uppercase tracking-[.2em] text-[#B7D2F4]">Imagem em breve</span></div>}</div><div className="h-1 bg-[#FF7A00] opacity-70 transition group-hover:opacity-100"/><div className="p-5"><div className="flex justify-center"><span className="rounded-full border border-emerald-400/20 bg-emerald-400/10 px-3 py-1 text-[9px] font-black tracking-widest text-emerald-300">ARQUIVOS ORGANIZADOS</span></div><h3 className="mt-4 text-center text-lg font-extrabold">{name}</h3><p className="mt-2 min-h-10 text-center text-sm leading-5 text-[#607C98]">{desc}</p>{name.startsWith("Natal")&&<p className="mt-3 text-xs font-bold text-[#FF7A00]">✨ 11 NOVOS · 21 ARQUIVOS</p>}{name.startsWith("Brinquedos Sensoriais")&&<p className="mt-3 text-xs font-bold text-[#FF7A00]">✨ 16 NOVOS</p>}{categoryExtraLinks[name] ? <div className="mt-5 grid grid-cols-2 gap-2">{categoryExtraLinks[name].map(link=><a key={link.url} href={link.url} target="_blank" rel="noreferrer" className={`${button} w-full px-2 text-xs`}>{link.label} ↗</a>)}</div> : <a href={url} target="_blank" rel="noreferrer" className={`${button} mt-5 w-full`}>{i===1?"VER 21 ARQUIVOS":"ACESSAR ARQUIVOS"} ↗</a>}</div></article>)}</div></div>}
        {section==="Comunidade" && <div className="animate-in fade-in duration-300">
          {heading("COMUNIDADE","Comunidade no Telegram","Troque ideias e modelos com outros makers.")}
          <section className={`${panel} mx-auto max-w-2xl p-6 text-center sm:p-8`}>
            <img src="/comunidade-telegram.webp" alt="Comunidade Impressão 3D no Telegram" className="mx-auto h-48 w-48 rounded-full object-cover sm:h-56 sm:w-56"/>
            <p className="mx-auto mt-6 max-w-lg leading-7 text-[#536D87]">Entre em grupos com milhares de pessoas que compartilham dicas, tiram dúvidas e trocam modelos de impressão 3D. São comunidades independentes, não administradas pela Prime Projetos 3D.</p>
            <div className="mt-6 grid gap-3 sm:grid-cols-3">
              {[["GRUPO 1","https://t.me/torrentstl/1"],["GRUPO 2","https://t.me/redestlbrasil"],["GRUPO 3","https://t.me/impressao3dbrasill"]].map(([n,u])=><a key={n} href={u} target="_blank" rel="noreferrer" className={`${button} w-full`}>{n} ↗</a>)}
            </div>
          </section>
        </div>}
        {section==="Calculadora" && calcMode==="choose" && <div className="mx-auto max-w-5xl animate-in fade-in duration-300 py-3">
          {heading("FERRAMENTAS DE PRECIFICAÇÃO","O que você deseja calcular?","Escolha a ferramenta ideal para descobrir seus custos, definir preços e aumentar sua margem de lucro.")}
          <div className="grid gap-5 md:grid-cols-2">
            <button onClick={()=>setCalcMode("piece")} className="group rounded-3xl border border-[#D7E8FF] bg-white p-7 text-left shadow-[0_12px_40px_rgba(23,105,255,.08)] transition hover:-translate-y-1 hover:border-[#FF7A00]/60 sm:p-9"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[#FFF0DF] text-3xl">🧮</div><p className="mt-6 text-xs font-black uppercase tracking-[.18em] text-[#FF7A00]">FERRAMENTA 01</p><h3 className="mt-2 text-2xl font-black text-[#173B63]">Calculadora de Impressão 3D</h3><p className="mt-3 leading-7 text-[#607C98]">Calcule o custo real da peça considerando filamento, energia, tempo de máquina, mão de obra, embalagem e outros gastos.</p><span className="mt-7 inline-flex items-center gap-2 rounded-xl bg-[#FF7A00] px-5 py-3 text-sm font-extrabold text-white">USAR CALCULADORA →</span></button>
            <button onClick={()=>setCalcMode("marketplace")} className="group rounded-3xl border border-[#D7E8FF] bg-white p-7 text-left shadow-[0_12px_40px_rgba(23,105,255,.08)] transition hover:-translate-y-1 hover:border-[#1769FF]/50 sm:p-9"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[#E7F2FF] text-3xl">📊</div><p className="mt-6 text-xs font-black uppercase tracking-[.18em] text-[#1769FF]">FERRAMENTA 02</p><h3 className="mt-2 text-2xl font-black text-[#173B63]">Simulador de Lucro por Marketplace</h3><p className="mt-3 leading-7 text-[#607C98]">Veja quanto sobra de cada venda depois das comissões, tarifas fixas, anúncios, impostos e frete subsidiado.</p><span className="mt-7 inline-flex items-center gap-2 rounded-xl bg-[#1769FF] px-5 py-3 text-sm font-extrabold text-white">SIMULAR MEU LUCRO →</span></button>
          </div><p className="mt-6 text-center text-xs text-[#8AA2BC]">Você pode alternar entre as ferramentas sempre que quiser.</p>
        </div>}
        {section==="Calculadora" && calcMode==="marketplace" && <MarketplaceSimulator cost={cost} panel={panel} field={field} money={money} onBack={()=>setCalcMode("choose")}/>}
        {section==="Calculadora" && calcMode==="piece" && <div className="animate-in fade-in duration-300">{heading("PRECIFICAÇÃO PROFISSIONAL","Calculadora completa de impressão 3D","Descubra o custo real de cada peça, simule taxas e compare preços de venda antes de anunciar.")}<div className="grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><section className={`${panel} p-5 sm:p-6`}><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-lg font-extrabold">1. Dados da impressão</h3><p className="mt-1 text-xs text-[#607C98]">Use os valores informados pelo seu fatiador e pela sua conta de energia.</p></div><button onClick={()=>{setWeight("120");setRoll("90");setHours("4");setHourCost("1.5");setEnergyRate("0.18");setPackaging("2.5");setLabor("5");setExtraCost("0");setWaste("10");setProfit("70");setFee("20");setTax("0");setQuantity("10")}} className="text-xs font-bold text-[#FF7A00] hover:underline">Carregar exemplo</button></div><div className="grid gap-4 sm:grid-cols-2"><label><span className={label}>Peso da peça (gramas)</span><input type="number" min="0" step=".1" value={weight} onChange={e=>setWeight(e.target.value)} className={field}/><small className="mt-1 block text-[#607C98]">Peso total indicado no fatiador</small></label><label><span className={label}>Preço do rolo de filamento (R$ / kg)</span><input type="number" min="0" step=".01" value={roll} onChange={e=>setRoll(e.target.value)} className={field}/><small className="mt-1 block text-[#607C98]">Valor pago pelo rolo de 1 kg</small></label><label><span className={label}>Tempo de impressão (horas)</span><input type="number" min="0" step=".1" value={hours} onChange={e=>setHours(e.target.value)} className={field}/></label><label><span className={label}>Desgaste / manutenção (R$ por hora)</span><input type="number" min="0" step=".01" value={hourCost} onChange={e=>setHourCost(e.target.value)} className={field}/></label><label><span className={label}>Energia elétrica (R$ por hora)</span><input type="number" min="0" step=".01" value={energyRate} onChange={e=>setEnergyRate(e.target.value)} className={field}/><small className="mt-1 block text-[#607C98]">Estimativa da energia consumida durante a impressão</small></label><label><span className={label}>Perda / margem para falhas (%)</span><input type="number" min="0" step=".1" value={waste} onChange={e=>setWaste(e.target.value)} className={field}/></label></div><h4 className="mb-3 mt-7 font-extrabold">2. Custos adicionais por peça</h4><div className="grid gap-4 sm:grid-cols-2"><label><span className={label}>Embalagem (R$)</span><input type="number" min="0" step=".01" value={packaging} onChange={e=>setPackaging(e.target.value)} className={field}/></label><label><span className={label}>Mão de obra / acabamento (R$)</span><input type="number" min="0" step=".01" value={labor} onChange={e=>setLabor(e.target.value)} className={field}/></label><label><span className={label}>Outros custos (R$)</span><input type="number" min="0" step=".01" value={extraCost} onChange={e=>setExtraCost(e.target.value)} className={field}/><small className="mt-1 block text-[#607C98]">Cola, tinta, ímã, bico, etiqueta ou acessórios</small></label><label><span className={label}>Quantidade do lote</span><input type="number" min="1" step="1" value={quantity} onChange={e=>setQuantity(e.target.value)} className={field}/></label></div><h4 className="mb-3 mt-7 font-extrabold">3. Estratégia de venda</h4><div className="grid gap-4 sm:grid-cols-3"><label><span className={label}>Lucro desejado sobre o custo (%)</span><input type="number" min="0" step=".1" value={profit} onChange={e=>setProfit(e.target.value)} className={field}/></label><label><span className={label}>Taxa marketplace / pagamento (%)</span><input type="number" min="0" max="95" step=".1" value={fee} onChange={e=>setFee(e.target.value)} className={field}/></label><label><span className={label}>Impostos (%)</span><input type="number" min="0" max="95" step=".1" value={tax} onChange={e=>setTax(e.target.value)} className={field}/></label></div><p className="mt-4 rounded-xl bg-[#F3F8FF] p-3 text-xs leading-5 text-[#607C98]">As taxas e os impostos são editáveis. Consulte os percentuais reais da sua plataforma e do seu enquadramento tributário.</p></section><section className={`${panel} h-fit p-5 sm:p-6`}><p className="text-xs font-black uppercase tracking-widest text-[#FF7A00]">RESULTADO AUTOMÁTICO</p><h3 className="mt-2 text-xl font-extrabold">Preço sugerido por peça</h3><p className="mt-4 text-4xl font-black tracking-tight text-[#FF7A00]">{cost>0?money(price):"Preencha os custos"}</p><p className="mt-1 text-xs text-[#607C98]">Inclui lucro desejado, taxas e impostos informados.</p><div className="my-5 space-y-3 border-y border-[#D7E8FF] py-4 text-sm"><div className="flex justify-between gap-3"><span className="text-[#607C98]">Filamento com perdas</span><b>{money(filamentCost)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Energia elétrica</span><b>{money(energyCost)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Desgaste / manutenção</span><b>{money(machineCost)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Embalagem</span><b>{money(Number(packaging)||0)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Mão de obra</span><b>{money(Number(labor)||0)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Outros custos</span><b>{money(Number(extraCost)||0)}</b></div><div className="flex justify-between gap-3 border-t border-[#D7E8FF] pt-3"><span className="font-bold">Custo total por peça</span><b>{money(cost)}</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Taxas + impostos</span><b>{(deductions*100).toFixed(1).replace(".",",")}%</b></div><div className="flex justify-between gap-3"><span className="text-[#607C98]">Lucro líquido estimado</span><b className="text-emerald-600">{money(netProfit)}</b></div></div><h4 className="font-extrabold">Sugestões de preço</h4><p className="mt-1 text-xs text-[#607C98]">Compare diferentes margens mantendo as taxas configuradas.</p><div className="mt-3 grid grid-cols-2 gap-2">{[["Conservador",30],["Competitivo",50],["Recomendado",70],["Premium",100]].map(([name,pct])=><div key={String(name)} className="rounded-xl border border-[#D7E8FF] bg-[#F3F8FF] p-3"><p className="text-xs font-bold text-[#607C98]">{name} · +{pct}%</p><p className="mt-1 text-lg font-black text-[#173B63]">{money(suggestedPrice(Number(pct)))}</p></div>)}</div><div className="mt-4 rounded-xl bg-[#FFF3E5] p-4"><p className="text-xs font-black uppercase tracking-wider text-[#E85D04]">Projeção do lote</p><div className="mt-2 flex justify-between gap-3 text-sm"><span className="text-[#607C98]">Faturamento bruto ({quantity} peças)</span><b>{money(batchTotal)}</b></div><div className="mt-1 flex justify-between gap-3 text-sm"><span className="text-[#607C98]">Lucro líquido do lote</span><b className="text-emerald-700">{money(netProfit*(Number(quantity)||0))}</b></div></div><p className="mt-4 text-xs leading-5 text-[#607C98]">Simulação estimada: confirme consumo elétrico, taxas, impostos e custos reais antes de definir o preço final.</p></section></div></div>}
        {section==="Bônus" && <div className="animate-in fade-in duration-300">{heading("CONTEÚDO EXTRA","Seus Bônus","Materiais extras para precificar, produzir melhor, fotografar e vender.")}<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{bonus.map(([icon,name,desc,url])=><article key={name} className={`${panel} group overflow-hidden transition duration-200 hover:-translate-y-1 hover:border-[#FF7A00]/35`}><div className="h-1 bg-[#FF7A00]"/>{name==="Impressora 3D Mais Rápida"&&<div className="flex h-40 items-center justify-center bg-[#1769FF]"><svg viewBox="0 0 96 96" className="h-20 w-20" fill="none" aria-hidden="true"><path d="M30 13h36v18H30z" stroke="white" strokeWidth="5" strokeLinejoin="round"/><path d="M20 36h56a8 8 0 0 1 8 8v20H68v19H28V64H12V44a8 8 0 0 1 8-8Z" stroke="white" strokeWidth="5" strokeLinejoin="round"/><path d="M36 53h24M36 64h24M36 75h24" stroke="#FFB347" strokeWidth="5" strokeLinecap="round"/><path d="m68 18 8-8m-8 8 8 8" stroke="#FFB347" strokeWidth="4" strokeLinecap="round"/></svg></div>}<div className="p-5"><div className="flex justify-center"><span className="rounded-full border border-[#FF7A00]/20 px-3 py-1 text-[10px] font-black uppercase tracking-widest text-[#FF7A00]">BÔNUS EXCLUSIVO</span></div><h3 className="mt-4 text-center text-lg font-extrabold">{name}</h3><p className="mt-2 min-h-12 text-center text-sm leading-6 text-[#607C98]">{desc}</p><a href={url} target={url.startsWith("http")?"_blank":undefined} rel={url.startsWith("http")?"noreferrer":undefined} className={`${button} mt-5 w-full`}>ACESSAR ↗</a></div></article>)}</div></div>}
      </div>
      <footer className="border-t border-white/[.07] px-5 py-5 text-center text-xs text-[#A9C8F2]">PRIME PROJETOS 3D <span className="mx-2 text-[#FF7A00]">•</span> Organize. Imprima. Venda.</footer>
    </main>
  </div>;
}
